def __init__(self):
    self.value = 0

def increment(self):
    self.value += 1

def __init__(self, balance=0):
    self.balance = balance

def deposit(self, amount):
    self.balance += amount

def withdraw(self, amount):
    if amount > self.balance:
        return False
    self.balance -= amount
    return True

def __init__(self):
